            <div class="management-table-wrap"><table class="management-table"><thead><tr><th scope="col">User</th><th scope="col">Role</th><th scope="col">Accounts</th><th scope="col">Last sign in</th><th scope="col">Access</th><th scope="col">Manage</th></tr></thead><tbody><?php foreach ($data['users'] as $user): ?><tr><td><strong><?= $escape($user['display_name']) ?></strong><small><?= $escape($user['email']) ?></small></td><td><?= $escape(ucfirst($user['role'])) ?></td><td><?= $escape($user['account_count']) ?></td><td><?= $escape($user['last_login_at'] ? substr((string) $user['last_login_at'], 0, 16) : 'Never') ?></td><td><span class="management-state <?= (int) $user['is_active'] === 1 ? 'is-active' : 'is-suspended' ?>"><?= (int) $user['is_active'] === 1 ? 'Active' : 'Suspended' ?></span></td><td><?php if ((int) $user['id'] === (int) $data['currentUser']['id']): ?><span class="management-self">Your account</span><?php else: ?><div class="management-user-actions"><form method="post" action="/users/update"><input type="hidden" name="_csrf" value="<?= $escape($data['csrfToken']) ?>"><input type="hidden" name="id" value="<?= $escape($user['id']) ?>"><input type="hidden" name="action" value="<?= (int) $user['is_active'] === 1 ? 'suspend' : 'activate' ?>"><button type="submit"><?= (int) $user['is_active'] === 1 ? 'Suspend' : 'Activate' ?></button></form><form method="post" action="/users/update"><input type="hidden" name="_csrf" value="<?= $escape($data['csrfToken']) ?>"><input type="hidden" name="id" value="<?= $escape($user['id']) ?>"><label class="sr-only" for="role-<?= $escape($user['id']) ?>">Role for <?= $escape($user['display_name']) ?></label><select id="role-<?= $escape($user['id']) ?>" name="action"><option value="customer" <?= $user['role'] === 'customer' ? 'selected' : '' ?> <?= $user['customer_id'] === null ? 'disabled' : '' ?>>Customer</option><option value="staff" <?= $user['role'] === 'staff' ? 'selected' : '' ?>>Staff</option><option value="admin" <?= $user['role'] === 'admin' ? 'selected' : '' ?>>Admin</option></select><button type="submit">Save role</button></form></div><?php endif; ?></td></tr><?php endforeach; ?></tbody></table><?php if ($data['users'] === []): ?><p class="management-empty">No users match this search.</p><?php endif; ?></div>
